def maxValue(n: int, index: int, maxSum: int) -> int:
    def get_sum(peak, count):
        if count == 0: return 0
        if peak >= count:
            return (peak + peak - count + 1) * count // 2
        return (peak + 1) * peak // 2 + (count - peak)
    lo, hi = 1, maxSum
    ans = 1
    while lo <= hi:
        mid = (lo + hi) // 2
        left_sum = get_sum(mid - 1, index)
        right_sum = get_sum(mid - 1, n - 1 - index)
        if left_sum + mid + right_sum <= maxSum:
            ans = mid
            lo = mid + 1
        else:
            hi = mid - 1
    return ans

